func (e *encoder) s_lateRef(v *lateRef) {
	e.token(v.tok)
	e.p_Decl(v.entity)
}

func (d *decoder) s_lateRef(v *lateRef) {
	v.tok = d.token()
	v.entity = d.p_Decl()
}
